payload=$(python3 - <<'PY'
import json
print(json.dumps({'files':[{'path':'index.html','content':open('/tmp/sshgrid.html').read()}],'label':'Social Media Growth Systems'}))
PY
)
sresp=$(curl -sS --max-time 30 -X POST 'https://sshgrid.com/api/v1/deploy' -H 'Content-Type: application/json' -d "$payload")
echo "SSHGRID_RESPONSE=$sresp"
surl=$(printf '%s' "$sresp" | python3 -c 'import sys,json; d=json.load(sys.stdin); print(d.get("url") or d.get("site_url") or d.get("public_url") or "")' 2>/dev/null)
if [[ "$surl" == https://* ]]; then
 code=$(curl -sS -L -o /tmp/ssh-live.html -w '%{http_code}' "$surl")
 if [ "$code" = "200" ] && grep -q 'smmfansfaster.com' /tmp/ssh-live.html; then echo "RESULT_URL=$surl"; else echo "SSHGRID_VERIFY_FAILED=$code $surl"; fi
